ible{outline:2px solid var(--primary);outline-offset:2px;border-radius:8px}.search .mi{font-size:21px;color:var(--muted)}.search input{width:100%;border:0;background:transparent;outline:none;min-height:46px;color:var(--ink)}.filters{display:flex;gap:6px;flex-wrap:wrap}.filter{border:1px solid var(--line);background:white;border-radius:22px;min-height:44px;padding:7px 16px;color:var(--muted)}.filter[aria-pressed=true]{background:var(--tonal);border-color:transparent;color:#15335f;font-weight:700}.select{max-width:230px;min-height:44px;padding:8px 34px 8px 14px;border:1px solid var(--line);border-radius:16px;background:white;color:var(--ink)}.section-line{display:flex;justify-content:space-between;align-items:center;gap:16px;color:var(--muted);font-size:12px;margin:0 0 14px}.notes-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));align-items:start;gap:18px}.note{border:1px solid rgba(32,38,48,.12);border-radius:20px;overflow:hidden;transition:transform .18s,border-color .18s;break-inside:avoid}.note:hover{transform:translateY(-2px);border-color:#9babc2}.note-open{display:block;width:100%;text-align:left;background:transparent;border:0;padding:20px;color:var(--ink);min-height:140px}.note h2{font-size:17px;line-height:1.45;margin-bottom:10px;overflow-wrap:anywhere}.note-body{white-space:pre-wrap;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:10;-webkit-box-orient:vertical;overflow:hidden;font-size:14px;line-height:1.7}.note.is-code .note-body{font-family:ui-monospace,Consolas,monospace;font-size:13px}.note-meta{display:flex;gap:5px;flex-wrap:wrap;margin-top:16px}.tag{font-size:11px;padding:3px 8px;border-radius:9px;background:rgba(255,255,255,.6)}.card-actions{display:flex;align-items:center;justify-content:space-between;gap:4px;padding:4px 12px 10px}.card-actions button{border:0;background:transparent;color:var(--muted);min-height:44px;min-width:44px;border-radius:12px}.card-actions button:hover{background:rgba(255,255,255,.6)}.