:0;overflow-wrap:anywhere}.error-bar{padding:14px 18px;background:#fce7e5;color:#8f241c;border-radius:14px;margin-bottom:20px}.error-bar[hidden]{display:none}dialog{border:0;border-radius:28px;background:white;color:var(--ink);padding:0;width:calc(100% - 32px);max-width:720px;max-height:calc(100dvh - 48px);box-shadow:0 24px 80px rgba(20,36,64,.18)}dialog::backdrop{background:rgba(24,34,50,.42);backdrop-filter:blur(4px)}.dialog-head{padding:24px 28px 20px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:20px;align-items:center}.dialog-head p{margin-top:5px;font-size:13px;color:var(--muted)}.dialog-body{padding:24px 28px;overflow:auto;max-height:calc(100dvh - 260px)}.dialog-foot{padding:18px 28px;border-top:1px solid var(--line);display:flex;justify-content:flex-end;gap:12px;background:white}.fields{display:grid;grid-template-columns:1fr 1fr;gap:18px}.field{display:grid;gap:7px;margin-bottom:18px}.field label{font-size:12px;font-weight:700}.field input,.field textarea,.field select{width:100%;min-height:46px;border:1px solid var(--line);border-radius:14px;padding:12px 14px;color:var(--ink);background:#f7f8fc}.field textarea{resize:vertical;line-height:1.65}.field:last-child{margin-bottom:0}.form-error{color:var(--danger);font-size:13px;margin-top:12px}.pair-dialog{max-width:440px}.pair-content{padding:40px 36px;text-align:center}.pair-mark{width:64px;height:64px;display:grid;place-items:center;border-radius:22px;background:var(--tonal);color:var(--primary);margin:0 auto 24px}.pair-mark .mi{font-size:30px}.pair-content h1{font-size:27px}.pair-content p{color:var(--muted);font-size:14px;margin:12px 0 24px}.pair-content input{width:100%;font:28px/1.5 ui-monospace,monospace;text-align:center;letter-spacing:12px;border:1px solid var(--line);background:var(--canvas);border-radius:18px;padding:14px;margin-bottom:18px}.pair-content .btn{width:100%}.pair-content small{display:block;margin-top:24px;font-size:12px}.toast{position:fixed;bottom:24